class Solution {
  public int valueAfterKSeconds(int n, int k) {
    final int MOD = 1_000_000_007;
    long[] a = new long[n];
    java.util.Arrays.fill(a, 1);
    for (int step = 0; step < k; step++) {
      for (int i = 1; i < n; i++) a[i] = (a[i] + a[i - 1]) % MOD;
    }
    return (int) a[n - 1];
  }
}
